<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import PortalLayout from '../layouts/PortalLayout.vue';
import api from '../services/api';
import { useAuthStore } from '../stores/auth';

const auth=useAuthStore(),student=computed(()=>auth.user?.role==='STUDENT'),faculty=computed(()=>auth.user?.role==='FACULTY'),admin=computed(()=>auth.user?.role==='ADMIN');
const teachers=ref([]),appointments=ref([]),availability=ref([]),exceptions=ref([]),slots=ref([]),settings=ref(null);
const form=ref({facultyId:'',date:'',startTime:'',endTime:'',purpose:'',meetingDetails:''});
const rule=ref({weekday:1,startTime:'09:00',endTime:'12:00',slotMinutes:30,bufferMinutes:0});
const exception=ref({date:'',reason:''}),busy=ref(false),loading=ref(true),error=ref(''),notice=ref('');
const proposal=ref({id:null,date:'',startTime:'',endTime:''});
const adminFilter=ref({facultyId:'',date:'',status:''}),appliedFilter=ref({facultyId:'',date:'',status:''}),filterLoading=ref(false);
const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const display=value=>new Date(value).toLocaleString('en-PH',{timeZone:'Asia/Manila',dateStyle:'medium',timeStyle:'short'});
async function load(){loading.value=true;error.value='';try{
  const [people,items,policy]=await Promise.all([api.get('/appointments/faculty'),api.get('/appointments',{params:admin.value?appliedFilter.value:{}}),api.get('/appointments/settings')]);
  teachers.value=people.data.data;appointments.value=items.data.data;settings.value=policy.data.data;
  if(faculty.value){const me=teachers.value.find(person=>person.userId===auth.user.id);if(me)form.value.facultyId=me.id;await loadAvailability();exceptions.value=(await api.get('/appointments/exceptions')).data.data;}
}catch(e){error.value=e.response?.data?.message||'Could not load appointments.';}finally{loading.value=false;}}
async function loadAvailability(){if(!form.value.facultyId)return;availability.value=(await api.get('/appointments/availability',{params:{facultyId:form.value.facultyId}})).data.data;}
async function loadSlots(){slots.value=[];form.value.startTime='';form.value.endTime='';if(!form.value.facultyId||!form.value.date)return;try{slots.value=(await api.get('/appointments/slots',{params:{facultyId:form.value.facultyId,date:form.value.date}})).data.data;}catch(e){error.value=e.response?.data?.message||'Could not load available slots.';}}
async function filterAppointments(){if(filterLoading.value)return;filterLoading.value=true;error.value='';const proposed={...adminFilter.value};try{appointments.value=(await api.get('/appointments',{params:proposed})).data.data;appliedFilter.value=proposed;}catch(e){error.value=e.response?.data?.message||'Could not filter appointments.';}finally{filterLoading.value=false;}}
async function clearAppointmentFilters(){adminFilter.value={facultyId:'',date:'',status:''};await filterAppointments();}
watch(()=>[form.value.facultyId,form.value.date],()=>{if(student.value)loadSlots();});
function choose(slot){if(!slot.available)return;form.value.startTime=slot.startTime;form.value.endTime=slot.endTime;}
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{const {data}=await api.post('/appointments',form.value);notice.value=data.message;form.value.purpose='';form.value.meetingDetails='';await load();await loadSlots();}catch(e){error.value=e.response?.data?.message||'Could not request appointment.';}finally{busy.value=false;}}
async function updateStatus(item,status){if(busy.value)return;let reason='';if(status==='REJECTED'||status==='CANCELLED'){reason=window.prompt(`Reason for ${status.toLowerCase()}?`)||'';if(status==='REJECTED'&&!reason.trim())return;}busy.value=true;error.value='';try{notice.value=(await api.patch(`/appointments/${item.id}/status`,{status,reason})).data.message;await load();}catch(e){error.value=e.response?.data?.message||'Could not update appointment.';}finally{busy.value=false;}}
async function addAvailability(){busy.value=true;error.value='';try{notice.value=(await api.post('/appointments/availability',rule.value)).data.message;await loadAvailability();}catch(e){error.value=e.response?.data?.message||'Could not save availability.';}finally{busy.value=false;}}
async function removeAvailability(item){if(!window.confirm('Remove this recurring availability? Existing appointments are kept.'))return;busy.value=true;try{await api.delete(`/appointments/availability/${item.id}`);await loadAvailability();}catch(e){error.value=e.response?.data?.message||'Could not remove availability.';}finally{busy.value=false;}}
async function addException(){busy.value=true;error.value='';try{notice.value=(await api.post('/appointments/exceptions',exception.value)).data.message;exceptions.value=(await api.get('/appointments/exceptions')).data.data;exception.value={date:'',reason:''};}catch(e){error.value=e.response?.data?.message||'Could not save exception.';}finally{busy.value=false;}}
async function saveSettings(){busy.value=true;error.value='';try{notice.value=(await api.put('/appointments/settings',settings.value)).data.message;}catch(e){error.value=e.response?.data?.message||'Could not save appointment policy.';}finally{busy.value=false;}}
async function propose(){if(busy.value)return;busy.value=true;error.value='';try{notice.value=(await api.post(`/appointments/${proposal.value.id}/proposal`,proposal.value)).data.message;proposal.value={id:null,date:'',startTime:'',endTime:''};await load();}catch(e){error.value=e.response?.data?.message||'Could not propose a new time.';}finally{busy.value=false;}}
async function accept(item){if(busy.value)return;busy.value=true;error.value='';try{notice.value=(await api.post(`/appointments/${item.id}/accept-proposal`)).data.message;await load();}catch(e){error.value=e.response?.data?.message||'Could not accept the proposed time.';}finally{busy.value=false;}}
onMounted(load);
</script>
<template><PortalLayout title="Appointments"><div class="dashboard content-page">
  <div class="page-heading"><div><p class="eyebrow">CONSULTATIONS · ASIA/MANILA</p><h2>Appointments</h2><p>Pending requests hold their selected slot until approved, rejected, or cancelled. Availability is checked again when you submit.</p></div></div>
  <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-message" role="status">{{notice}}</p><p v-if="loading" class="empty">Loading appointments…</p>
  <template v-else>
    <section v-if="student" class="panel"><h2>Request a consultation</h2><form class="stack-form" @submit.prevent="submit"><div class="two-fields"><label>Teacher<select v-model="form.facultyId" required><option value="">Select teacher</option><option v-for="person in teachers" :key="person.id" :value="person.id">{{person.name}} {{person.position?`· ${person.position}`:''}}</option></select></label><label>Date (Asia/Manila)<input v-model="form.date" type="date" required/></label></div><div class="slot-grid" role="group" aria-label="Consultation times"><button v-for="slot in slots" :key="slot.startTime" type="button" class="secondary-button" :class="{selected:form.startTime===slot.startTime}" :aria-pressed="form.startTime===slot.startTime" :disabled="!slot.available" :title="slot.reason||''" @click="choose(slot)">{{slot.startTime}}–{{slot.endTime}} <small v-if="!slot.available">Unavailable</small></button></div><p v-if="form.date&&form.facultyId&&!slots.length" class="field-help">No consultation hours have been published for this date.</p><label>Purpose<textarea v-model="form.purpose" required maxlength="500" rows="3"/></label><label>Meeting details (optional)<input v-model="form.meetingDetails" maxlength="500" placeholder="Topic or accessibility needs"/></label><button class="primary" :disabled="busy||!form.startTime">{{busy?'Requesting…':'Request appointment'}}</button></form></section>
    <section v-if="faculty" class="panel"><h2>Recurring availability</h2><p class="field-help">Slots are generated from these weekly windows. Existing requests are not cancelled when you remove a window.</p><div class="record-list"><div v-for="item in availability" :key="item.id" class="record-row"><span>{{days[item.weekday-1]}} {{item.startTime}}–{{item.endTime}} · {{item.slotMinutes}}-minute slots · {{item.bufferMinutes}}-minute buffer</span><button class="text-button" @click="removeAvailability(item)">Remove</button></div></div><form class="stack-form" @submit.prevent="addAvailability"><div class="two-fields"><label>Weekday<select v-model.number="rule.weekday"><option v-for="(day,index) in days" :key="day" :value="index+1">{{day}}</option></select></label><label>Slot length (minutes)<input v-model.number="rule.slotMinutes" type="number" min="15" max="120" required/></label></div><div class="two-fields"><label>Starts<input v-model="rule.startTime" type="time" required/></label><label>Ends<input v-model="rule.endTime" type="time" required/></label></div><label>Buffer between slots (minutes)<input v-model.number="rule.bufferMinutes" type="number" min="0" max="60" required/></label><button class="primary" :disabled="busy">Add availability</button></form></section>
    <section v-if="faculty" class="panel"><h2>Unavailable dates</h2><form class="stack-form" @submit.prevent="addException"><label>Date<input v-model="exception.date" type="date" required/></label><label>Reason (optional)<input v-model="exception.reason" maxlength="200"/></label><button class="primary" :disabled="busy">Block date</button></form><p v-for="item in exceptions" :key="item.id" class="field-help">{{String(item.date).slice(0,10)}} · {{item.reason||'Unavailable'}}</p></section>
    <section v-if="admin&&settings" class="panel narrow-panel"><h2>Department appointment policy</h2><form class="stack-form" @submit.prevent="saveSettings"><label>Advance booking window (days)<input v-model.number="settings.advanceDays" type="number" min="1" max="180" required/></label><label>Student cancellation notice (hours)<input v-model.number="settings.cancellationHours" type="number" min="0" max="168" required/></label><button class="primary" :disabled="busy">Save policy</button></form></section>
    <section class="panel"><h2>{{student?'My requests':faculty?'Consultation requests':'Department appointments'}}</h2><form v-if="admin" class="stack-form" @submit.prevent="filterAppointments"><div class="two-fields"><label>Teacher<select v-model="adminFilter.facultyId"><option value="">All teachers</option><option v-for="person in teachers" :key="person.id" :value="person.id">{{person.name}}</option></select></label><label>Date (Asia/Manila)<input v-model="adminFilter.date" type="date"/></label></div><label>Status<select v-model="adminFilter.status"><option value="">All statuses</option><option v-for="state in ['PENDING','APPROVED','REJECTED','COMPLETED','CANCELLED','NO_SHOW']" :key="state" :value="state">{{state.replace('_',' ')}}</option></select></label><div class="inline-actions"><button class="secondary-button" :disabled="filterLoading">{{filterLoading?'Applying filters…':'Apply filters'}}</button><button type="button" class="text-button" :disabled="filterLoading" @click="clearAppointmentFilters">Clear filters</button></div><p class="field-help">{{appointments.length}} recent match{{appointments.length===1?'':'es'}}{{appliedFilter.date?` on ${new Date(`${appliedFilter.date}T12:00:00+08:00`).toLocaleDateString('en-PH',{dateStyle:'long',timeZone:'Asia/Manila'})}`:''}}. Showing up to 200. Consultation purposes are private to participants.</p></form><p v-if="filterLoading" role="status">Loading matching appointments…</p><div v-else-if="appointments.length" class="record-list"><article v-for="item in appointments" :key="item.id" class="appointment-row"><div><strong>{{display(item.startsAt)}} · {{item.status}}</strong><span>{{student?item.facultyName:item.studentName}} · {{item.facultyName}}</span><p v-if="item.purpose">{{item.purpose}}</p><small v-if="item.responseReason">Response: {{item.responseReason}}</small><p v-if="item.proposedStartsAt">Proposed: {{display(item.proposedStartsAt)}}. Original booking remains until accepted.</p></div><div class="inline-actions"><template v-if="faculty&&item.status==='PENDING'"><button class="text-button" :disabled="busy" @click="updateStatus(item,'APPROVED')">Approve</button><button class="text-button" :disabled="busy" @click="updateStatus(item,'REJECTED')">Reject</button></template><template v-if="faculty&&item.status==='APPROVED'"><button class="text-button" :disabled="busy" @click="updateStatus(item,'COMPLETED')">Complete</button><button class="text-button" :disabled="busy" @click="updateStatus(item,'NO_SHOW')">No-show</button><button class="text-button" :disabled="busy" @click="updateStatus(item,'CANCELLED')">Cancel</button></template><button v-if="student&&['PENDING','APPROVED'].includes(item.status)" class="text-button" :disabled="busy" @click="updateStatus(item,'CANCELLED')">Cancel</button><button v-if="(student||faculty)&&['PENDING','APPROVED'].includes(item.status)" class="text-button" @click="proposal={id:item.id,date:'',startTime:'',endTime:''}">Propose new time</button><button v-if="item.proposedStartsAt&&item.proposedBy!==auth.user.id" class="text-button" :disabled="busy" @click="accept(item)">Accept new time</button></div><form v-if="proposal.id===item.id" class="stack-form" @submit.prevent="propose"><div class="two-fields"><label>New date (Asia/Manila)<input v-model="proposal.date" type="date" required/></label><label>Start<input v-model="proposal.startTime" type="time" required/></label></div><label>End<input v-model="proposal.endTime" type="time" required/></label><p class="field-help">The other person must accept. The proposed slot is rechecked then; it is not held now.</p><div class="inline-actions"><button class="primary" :disabled="busy">Send proposal</button><button type="button" class="secondary-button" @click="proposal.id=null">Cancel</button></div></form></article></div><p v-else class="empty">{{error?'Could not load appointments.':admin?'No appointments match the applied filters. Try All statuses or clear the date.':'No appointments to show.'}}</p></section>
  </template>
</div></PortalLayout></template>
